-- NARRATIVE-CATALOG-ALIGN-CANDIDATE-001; INSTALL; due soli campi, nessun nuovo oggetto permanente.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='20s';
SET LOCAL TIME ZONE 'UTC';
DO $catalog_alignment$
DECLARE expected_c jsonb := $before_c${"attivazione": "istantanea", "bersaglio": "Un PG avversario o una sua figura di Moltiplicazione valida entro il raggio", "category": "Arte segreta · Trappola e immobilizzazione", "chakra_cost": 5, "clan": "Sabaku", "colpisce_formazione": false, "consumption_type": "ad_utilizzo", "created_at": "2026-07-14T16:58:10.080375+00:00", "danno_base": 0, "danno_effetto": "Con Controllo della Sabbia attivo, crea un solo Clone entro 3 m dall’utilizzatore: consuma l’azione principale e 5 chakra, impegnando 5 unità di sabbia disponibili nella giara. Il Clone si innesca automaticamente quando un PG avversario o una sua figura di Moltiplicazione valida è entro 2 m, anche subito alla creazione. Una copia consuma l’unico innesco senza applicare la presa al proprietario. Contro il PG, la cattura confronta ⌊(Kekkei Genkai + Ninjutsu) / 5⌋ + 2d10 del creatore con ⌊(Velocità + Taijutsu) / 5⌋ + 2d10 del bersaglio; la parità favorisce la cattura. Il successo immobilizza il PG senza infliggere danni; il fallimento esaurisce il Clone. Il bersaglio può tentare di liberarsi con la propria azione principale e senza chakra: ⌊(Forza + Taijutsu) / 5⌋ + 2d10 contro ⌊pool della presa registrato / 5⌋ + 2d10; serve un risultato superiore e si può tentare una sola volta per proprio turno. Se la presa interrompe l’avvicinamento prima della dichiarazione di attacco o Moltiplicazione, il movimento percorso e la presa restano registrati e la principale rimane disponibile. Il Clone dura al massimo 3 turni del creatore, incluso quello di creazione. Termina anche quando la presa viene sciolta, il bersaglio è fuori combattimento, l’utilizzatore è assente o fuori combattimento, Controllo della Sabbia viene spento, la sabbia non è utilizzabile o lo scontro termina. Alla conclusione si libera la quota impegnata, senza creare nuova sabbia né rimborsare chakra. Non ha un mantenimento proprio; i costi dell’Innata restano separati.", "description": "Il Sabaku modella la sabbia della propria giara in una sagoma che funge da trappola. Quando un avversario si avvicina, la sabbia scatta per avvolgerlo e trattenerlo. Il Clone può essere ingannato dalle copie create con la Moltiplicazione.", "di_scena": false, "difensiva": false, "disciplina": "Abilità", "durata": "Massimo 3 turni del creatore, incluso quello di creazione", "gittata": "corta", "grado": "D", "gruppo_esclusivo": null, "id": "617484d6-af7b-41c3-a37f-615b22818421", "is_active": true, "is_innata": false, "is_leggendaria": false, "level": null, "macro": "clan", "name": "Clone di Sabbia", "portata": "Piazzamento entro 3 m; innesco entro 2 m dal Clone", "potenza": null, "ramo_esclusivo": null, "req_cercoterio": null, "req_corp": null, "req_elements": null, "req_elements_mode": null, "req_famiglia": null, "req_grade": "Genin", "req_perk": null, "req_ramo": null, "req_stat": "Kekkei Genkai", "req_stat2": null, "req_stat2_value": null, "req_stat_value": 30, "req_taglia": null, "req_tecnica": "001f907c-8f32-4758-8a16-ad1730e72c59", "requirements": "Clan Sabaku · grado Genin · Kekkei Genkai ≥30 · Controllo della Sabbia L1 posseduto e attivo · almeno 5 unità disponibili nella propria giara · nessun altro Clone di Sabbia attivo.", "ricarica": "Un solo Clone attivo; nuovo utilizzo dopo la conclusione del precedente, con azione e costi disponibili", "rivela_originale": false, "sort": 11, "tipo_azione": "Creazione con azione principale; innesco automatico della trappola", "trainings_required": 1, "uso": "principale", "xp_cost": 50}$before_c$::jsonb;
 expected_j jsonb := $before_j${"action_type": "istantanea", "atk_discipline": "ninjutsu", "atk_natural": "mente", "category": "Ninjutsu", "chakra_cost": 10, "colpisce_formazione": false, "created_at": "2026-07-12T11:38:06.778389+00:00", "damage_base": null, "defense_hint": "Chi percepisce il chakra (Mente) distingue le copie.", "di_scena": false, "difensiva": false, "diversivo": true, "effect": "Crei copie illusorie mentre ti riposizioni. Le copie possono confondere il primo attacco diretto ricevuto: la difesa usa Mente + Ninjutsu.", "gittata": "contatto", "id": "c6e31b7b-38fe-4b4f-b3c7-05f3e922d193", "is_active": true, "kind": "jutsu", "limits": "Azione principale, una volta per round o scambio. Le copie non si accumulano, si consumano al primo attacco diretto o scadono al tuo turno successivo. Se la copia viene colpita non subisci danno né sfioramento; se l'originale è individuato l'attacco si risolve normalmente.", "name_it": "Moltiplicazione del corpo", "name_romaji": "Bunshin no Jutsu", "nature": null, "origin": "manga", "power": 1, "rank": "E", "requirements": "Tecnica base di accademia", "rivela_originale": false, "sort": 2, "uso": "principale"}$before_j$::jsonb;
 target_c jsonb := $after_c${"attivazione": "istantanea", "bersaglio": "Un PG avversario o una sua figura di Moltiplicazione valida entro il raggio", "category": "Arte segreta · Trappola e immobilizzazione", "chakra_cost": 5, "clan": "Sabaku", "colpisce_formazione": false, "consumption_type": "ad_utilizzo", "created_at": "2026-07-14T16:58:10.080375+00:00", "danno_base": 0, "danno_effetto": "Con Controllo della Sabbia attivo, crea un solo Clone entro 3 m dall’utilizzatore: consuma l’azione principale e 5 chakra, impegnando 5 unità di sabbia disponibili nella giara. Il Clone si innesca automaticamente quando un PG avversario o una sua figura di Moltiplicazione valida è entro 2 m, anche subito alla creazione. Una copia consuma l’unico innesco senza applicare la presa al proprietario. Contro il PG, la cattura confronta ⌊(Kekkei Genkai + Ninjutsu) / 5⌋ + 2d10 del creatore con ⌊(Velocità + Taijutsu) / 5⌋ + 2d10 del bersaglio; la parità favorisce la cattura. Il successo immobilizza il PG senza infliggere danni; il fallimento esaurisce il Clone. Il bersaglio può tentare di liberarsi con la propria azione principale e senza chakra: ⌊(Forza + Taijutsu) / 5⌋ + 2d10 contro ⌊pool della presa registrato / 5⌋ + 2d10; serve un risultato superiore e si può tentare una sola volta per proprio turno. Se la presa interrompe l’avvicinamento prima della dichiarazione di attacco o Moltiplicazione, il movimento percorso e la presa restano registrati e la principale rimane disponibile. Il Clone dura al massimo 3 turni del creatore, incluso quello di creazione. Termina anche quando la presa viene sciolta, il bersaglio è fuori combattimento, l’utilizzatore è assente o fuori combattimento, Controllo della Sabbia viene spento, la sabbia non è utilizzabile o lo scontro termina. Alla conclusione si libera la quota impegnata, senza creare nuova sabbia né rimborsare chakra. Non ha un mantenimento proprio; i costi dell’Innata restano separati.", "description": "La sabbia della propria giara prende la sagoma del Sabaku, formando un corpo compatto che ne richiama l’aspetto. È una figura di sabbia, concreta e riconoscibile nella sua materia. Quando la tecnica si esaurisce, perde coesione: la sagoma si sfalda e ricade al suolo in una massa di granelli.", "di_scena": false, "difensiva": false, "disciplina": "Abilità", "durata": "Massimo 3 turni del creatore, incluso quello di creazione", "gittata": "corta", "grado": "D", "gruppo_esclusivo": null, "id": "617484d6-af7b-41c3-a37f-615b22818421", "is_active": true, "is_innata": false, "is_leggendaria": false, "level": null, "macro": "clan", "name": "Clone di Sabbia", "portata": "Piazzamento entro 3 m; innesco entro 2 m dal Clone", "potenza": null, "ramo_esclusivo": null, "req_cercoterio": null, "req_corp": null, "req_elements": null, "req_elements_mode": null, "req_famiglia": null, "req_grade": "Genin", "req_perk": null, "req_ramo": null, "req_stat": "Kekkei Genkai", "req_stat2": null, "req_stat2_value": null, "req_stat_value": 30, "req_taglia": null, "req_tecnica": "001f907c-8f32-4758-8a16-ad1730e72c59", "requirements": "Clan Sabaku · grado Genin · Kekkei Genkai ≥30 · Controllo della Sabbia L1 posseduto e attivo · almeno 5 unità disponibili nella propria giara · nessun altro Clone di Sabbia attivo.", "ricarica": "Un solo Clone attivo; nuovo utilizzo dopo la conclusione del precedente, con azione e costi disponibili", "rivela_originale": false, "sort": 11, "tipo_azione": "Creazione con azione principale; innesco automatico della trappola", "trainings_required": 1, "uso": "principale", "xp_cost": 50}$after_c$::jsonb;
 target_j jsonb := $after_j${"action_type": "istantanea", "atk_discipline": "ninjutsu", "atk_natural": "mente", "category": "Ninjutsu", "chakra_cost": 10, "colpisce_formazione": false, "created_at": "2026-07-12T11:38:06.778389+00:00", "damage_base": null, "defense_hint": "Chi percepisce il chakra (Mente) distingue le copie.", "di_scena": false, "difensiva": false, "diversivo": true, "effect": "Crei copie illusorie del tuo aspetto mentre ti riposizioni. Le immagini non hanno solidità e possono disporsi entro cinque metri da te: non possono afferrare, sostenere un peso o infliggere ferite. Le copie possono confondere il primo attacco diretto ricevuto: la difesa usa Mente + Ninjutsu. Quando una copia viene colpita o il suo effetto termina, svanisce in una nuvoletta bianca.", "gittata": "contatto", "id": "c6e31b7b-38fe-4b4f-b3c7-05f3e922d193", "is_active": true, "kind": "jutsu", "limits": "Azione principale, una volta per round o scambio. Le copie non si accumulano, si consumano al primo attacco diretto o scadono al tuo turno successivo. Se la copia viene colpita non subisci danno né sfioramento; se l'originale è individuato l'attacco si risolve normalmente.", "name_it": "Moltiplicazione del corpo", "name_romaji": "Bunshin no Jutsu", "nature": null, "origin": "manga", "power": 1, "rank": "E", "requirements": "Tecnica base di accademia", "rivela_originale": false, "sort": 2, "uso": "principale"}$after_j$::jsonb;
 actual_c jsonb; actual_j jsonb; n integer;
BEGIN
 IF EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid IN ('public.clan_techniques'::regclass,'public.jutsu'::regclass) AND NOT tgisinternal) THEN
  RAISE EXCEPTION 'catalog_application_trigger_drift' USING ERRCODE='40001';
 END IF;
 SELECT to_jsonb(c) INTO actual_c FROM public.clan_techniques c WHERE c.id=(expected_c->>'id')::uuid FOR UPDATE;
 SELECT to_jsonb(j) INTO actual_j FROM public.jutsu j WHERE j.id=(expected_j->>'id')::uuid FOR UPDATE;
 IF actual_c IS DISTINCT FROM expected_c OR actual_j IS DISTINCT FROM expected_j THEN
  RAISE EXCEPTION 'catalog_baseline_drift' USING ERRCODE='40001';
 END IF;
 UPDATE public.clan_techniques SET description=target_c->>'description' WHERE id=(expected_c->>'id')::uuid AND description IS NOT DISTINCT FROM expected_c->>'description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'catalog_clone_affected_rows' USING ERRCODE='40001'; END IF;
 UPDATE public.jutsu SET effect=target_j->>'effect' WHERE id=(expected_j->>'id')::uuid AND effect IS NOT DISTINCT FROM expected_j->>'effect';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'catalog_multiplication_affected_rows' USING ERRCODE='40001'; END IF;
 SELECT to_jsonb(c) INTO actual_c FROM public.clan_techniques c WHERE c.id=(expected_c->>'id')::uuid;
 SELECT to_jsonb(j) INTO actual_j FROM public.jutsu j WHERE j.id=(expected_j->>'id')::uuid;
 IF actual_c IS DISTINCT FROM target_c OR actual_j IS DISTINCT FROM target_j THEN
  RAISE EXCEPTION 'catalog_postflight_or_other_columns_drift' USING ERRCODE='40001';
 END IF;
END $catalog_alignment$;
COMMIT;
